"""OCR producer contract. Policy bytes are generated by internal/ocr, not editable."""
import hashlib
import json
import math
from pathlib import Path
import struct
import unicodedata
import zlib

from cache_snapshot import canonical_manifest

HERE = Path(__file__).parent
BASE = "sha256:52f4a40c9f0169e87783b138200e24c8e96492fccf244b9d329ec1e05e45f626"
MODEL = "PP-OCRv5_server"
INPUT = json.loads((HERE / "ocr-input.generated.json").read_bytes())
OUTPUT = json.loads((HERE / "ocr-output.generated.json").read_bytes())
MANIFEST = json.loads((HERE / "ocr-manifest.json").read_bytes())
MAX_BYTES = INPUT["max_output_bytes"]


class InputLimit(Exception): pass
class InvalidMedia(Exception): pass
class InvalidInput(Exception): pass
class InvalidOutput(Exception): pass


def expected_identity():
    digest = hashlib.sha256(BASE.encode())
    for name in ("ocr_contract.py", "ocr_scheduler.py", "ocr_engine.py", "ocr_worker.py", "ocr_server.py", "ocr_runtime.py",
                 "ocr-input.generated.json", "ocr-output.generated.json", "ocr-manifest.json"):
        digest.update(name.encode() + b"\0" + (HERE / name).read_bytes())
    by_path = {e["path"]: e["sha256"] for e in MANIFEST}
    return {"version": 1, "protocol": "foliopath-ocr-v1", "model": MODEL,
            "detector_sha256": by_path[f"ocr/{MODEL}/detection/model.onnx"],
            "recognizer_sha256": by_path[f"ocr/{MODEL}/recognition/model.onnx"],
            "input_contract_sha256": hashlib.sha256((HERE / "ocr-input.generated.json").read_bytes()).hexdigest(),
            "output_contract_sha256": hashlib.sha256((HERE / "ocr-output.generated.json").read_bytes()).hexdigest(),
            "runtime_contract_sha256": digest.hexdigest(),
            "cache_manifest_sha256": hashlib.sha256(canonical_manifest(MANIFEST)).hexdigest()}


def fingerprint():
    return hashlib.sha256(json.dumps(expected_identity(), sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def validate_png(payload):
    if not payload: raise InvalidMedia()
    if len(payload) > MAX_BYTES: raise InputLimit()
    if payload[:8] != b"\x89PNG\r\n\x1a\n": raise InvalidMedia()
    pos, count, idat, ended, dimensions = 8, 0, False, False, None
    while pos < len(payload):
        if pos + 12 > len(payload): raise InvalidMedia()
        size = struct.unpack_from(">I", payload, pos)[0]
        kind = payload[pos + 4:pos + 8]
        end = pos + 12 + size
        if end > len(payload): raise InvalidMedia()
        if zlib.crc32(memoryview(payload)[pos+4:end-4]) != struct.unpack_from(">I", payload, end-4)[0]: raise InvalidMedia()
        count += 1
        if count > 4096: raise InputLimit()
        if count == 1:
            if kind != b"IHDR" or size != 13: raise InvalidMedia()
            w, h, depth, color, compression, filtering, interlace = struct.unpack_from(">IIBBBBB", payload, pos+8)
            if min(w,h) < INPUT["min_dimension"] or max(w,h) > INPUT["max_dimension"] or w*h > INPUT["max_output_pixels"]: raise InputLimit()
            if (depth,color,compression,filtering,interlace) != (8,2,0,0,0): raise InvalidInput()
            dimensions = (w,h)
        elif kind == b"IDAT":
            if ended: raise InvalidMedia()
            idat = True
        elif kind == b"IEND":
            if size != 0 or not idat or end != len(payload): raise InvalidMedia()
            return dimensions
        elif kind == b"pHYs":
            if idat: ended = True
            if size != 9: raise InvalidMedia()
        else:
            # Text/EXIF/ICC/animation and unknown chunks are outside the prepared
            # image contract, not silently transformed in the HTTP process.
            raise InvalidInput()
        pos = end
    raise InvalidMedia()


def valid_box(box):
    if not isinstance(box,list) or len(box)!=8 or any(type(v) not in (float,int) or not math.isfinite(v) or not 0<=v<=1 for v in box):
        raise InvalidOutput()
    points=list(zip(box[::2],box[1::2]));crosses=[]
    for i in range(4):
        a,b,c=points[i],points[(i+1)%4],points[(i+2)%4]
        crosses.append((b[0]-a[0])*(c[1]-b[1])-(b[1]-a[1])*(c[0]-b[0]))
    if not(all(v>0 for v in crosses) or all(v<0 for v in crosses)): raise InvalidOutput()


def normalize(lines):
    if not isinstance(lines,list) or len(lines)>OUTPUT["max_lines"]: raise InvalidOutput()
    normalized=[];total=0
    for line in lines:
        if not isinstance(line,dict) or set(line)!={"text","box","detection_score","recognition_score"}: raise InvalidOutput()
        text=line["text"]
        if not isinstance(text,str) or not text.strip() or len(text)>OUTPUT["max_line_runes"] or any(unicodedata.category(c) in ("Cc","Cs") for c in text): raise InvalidOutput()
        text=unicodedata.normalize("NFC",text);total+=len(text)
        if len(text)>OUTPUT["max_line_runes"] or total>OUTPUT["max_text_runes"]: raise InvalidOutput()
        valid_box(line["box"])
        for key,minimum in (("detection_score",OUTPUT["min_detection"]),("recognition_score",OUTPUT["min_recognition"])):
            value=line[key]
            if type(value) not in (float,int) or not math.isfinite(value) or not minimum<=value<=1: raise InvalidOutput()
        normalized.append({**line,"text":text})
    return {"identity":fingerprint(),"lines":normalized}


if __name__ == "__main__": print(json.dumps(expected_identity(),sort_keys=True,separators=(",",":")))
